using System.Security.Principal;

namespace Daqifi.Desktop.Common;

/// <summary>
/// Single source of truth for where DAQiFi stores its application data (database and logs).
///
/// Production (elevated) runs use the machine-wide <c>CommonApplicationData</c>
/// (<c>%ProgramData%</c>) location. Any un-elevated run — the UI-test harness
/// (<c>DAQIFI_TEST_MODE=1</c>) <b>or</b> a normal non-admin Debug launch (the Debug build
/// ships an <c>asInvoker</c> manifest) — uses the per-user-writable
/// <c>LocalApplicationData</c> (<c>%LocalAppData%</c>) location instead, because a standard
/// token cannot write an admin-owned machine-wide store (which otherwise crashes startup
/// with a read-only database and/or fails to write logs).
///
/// Keeping the database and the logs under the same root avoids split or lost data.
/// </summary>
// @port: Daqifi.Desktop.Common.AppDataPaths
public static class AppDataPaths
{
    /// <summary>
    /// <c>true</c> when launched in unattended UI-test mode (environment variable
    /// <c>DAQIFI_TEST_MODE=1</c>).
    /// </summary>
    // @port: Daqifi.Desktop.Common.AppDataPaths.IsTestMode
    public static bool IsTestMode { get; } =
        string.Equals(Environment.GetEnvironmentVariable("DAQIFI_TEST_MODE"), "1", StringComparison.Ordinal);

    /// <summary>
    /// Optional UI-test export target directory. When the environment variable
    /// <c>DAQIFI_TEST_EXPORT_PATH</c> is set, the logging-session export commands write
    /// straight into this directory (one <c>{session}.csv</c> per session) and skip the
    /// interactive <c>SaveFileDialog</c>/<c>FolderBrowserDialog</c> entirely, so the FlaUI
    /// harness can export to a known location with zero modal interaction. <c>null</c> in
    /// normal and production runs, where the dialog behaviour is unchanged. Mirrors
    /// <see cref="IsTestMode"/> — a one-liner the harness sets on the child process,
    /// impossible to trigger accidentally in production (the variable is never set there).
    /// </summary>
    // @port: Daqifi.Desktop.Common.AppDataPaths.TestExportPath
    public static string? TestExportPath { get; } = ResolveTestExportPath();

    /// <summary><c>true</c> when the current process is running with administrator rights.</summary>
    // @port: Daqifi.Desktop.Common.AppDataPaths.IsElevated
    public static bool IsElevated { get; } = ComputeIsElevated();

    /// <summary>
    /// Root DAQiFi data directory for the current elevation/test context. Honors an explicit
    /// <c>DAQIFI_DATA_DIR</c> override (absolute-ised) when set; otherwise per-user when the
    /// process is un-elevated or in test mode, and machine-wide otherwise. The override lets a
    /// test/tooling boot (e.g. the parity-audit capture harness) point the database and logs at
    /// an isolated throwaway directory so it never reads or migrates the developer's real
    /// <c>DAQiFiDatabase.db</c>. Mirrors <see cref="TestExportPath"/>: a one-liner the harness
    /// sets on the child process, impossible to trigger accidentally in production (the variable
    /// is never set there).
    /// </summary>
    // @port: Daqifi.Desktop.Common.AppDataPaths.DataDirectory
    public static string DataDirectory { get; } = ResolveDataDirectory();

    // Downstream addition (no upstream counterpart): resolves the data root, preferring the
    // DAQIFI_DATA_DIR override before falling back to the elevation/test-mode default.
    private static string ResolveDataDirectory()
    {
        var overrideDir = Environment.GetEnvironmentVariable("DAQIFI_DATA_DIR");
        if (!string.IsNullOrWhiteSpace(overrideDir))
        {
            // An explicit override fails CLOSED with a DIAGNOSTIC error. Absolute-ise it (so a
            // relative value resolves deterministically, not against the GUI process's incidental
            // working directory) and eagerly create it, so any bad value — invalid path syntax, a
            // missing drive, an inaccessible root, or a path that is actually a file — surfaces as
            // a clear exception naming the env var and value. The whole point of the override is to
            // NOT touch the developer's real DAQiFiDatabase.db, so a bad override must fail loudly:
            // neither a silent fallback to the real store (a headless test would then read/migrate
            // it) nor an opaque type-init/CreateDirectory crash deep in startup is acceptable. The
            // default path below is unchanged — App.Initialize/InitializeMobile create it as before.
            try
            {
                var resolved = Path.GetFullPath(overrideDir.Trim());
                Directory.CreateDirectory(resolved);
                // CreateDirectory also succeeds on a pre-existing but read-only directory, so probe
                // actual writability with a create-and-delete temp file. Without this, an ACL/
                // permission problem would defer the failure downstream to SQLite/logging and lose
                // this DAQIFI_DATA_DIR-specific diagnostic — the whole point of failing closed here.
                var probe = Path.Combine(resolved, ".daqifi-write-probe-" + Guid.NewGuid().ToString("N"));
                File.WriteAllText(probe, string.Empty);
                File.Delete(probe);
                return resolved;
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException(
                    $"DAQIFI_DATA_DIR is set to '{overrideDir}', which could not be used as a " +
                    "writable application data directory. Set it to a writable directory path, or unset it.", ex);
            }
        }

        return Path.Combine(
            Environment.GetFolderPath(IsTestMode || !IsElevated
                ? Environment.SpecialFolder.LocalApplicationData
                : Environment.SpecialFolder.CommonApplicationData),
            "DAQiFi");
    }

    /// <summary>Directory where application logs are written.</summary>
    // @port: Daqifi.Desktop.Common.AppDataPaths.LogDirectory
    public static string LogDirectory { get; } = Path.Combine(DataDirectory, "Logs");

    // @port: Daqifi.Desktop.Common.AppDataPaths.ResolveTestExportPath
    private static string? ResolveTestExportPath()
    {
        var raw = Environment.GetEnvironmentVariable("DAQIFI_TEST_EXPORT_PATH");
        return string.IsNullOrWhiteSpace(raw) ? null : raw.Trim();
    }

    // @port: Daqifi.Desktop.Common.AppDataPaths.ComputeIsElevated
    private static bool ComputeIsElevated()
    {
        if (!OperatingSystem.IsWindows())
        {
            return false;
        }

        try
        {
            using var identity = WindowsIdentity.GetCurrent();
            return new WindowsPrincipal(identity).IsInRole(WindowsBuiltInRole.Administrator);
        }
        catch
        {
            // If the elevation check fails for any reason, treat the process as un-elevated
            // so it falls back to the always-writable per-user location.
            return false;
        }
    }
}
